1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"time"
9		"unicode"
10	
11		"github.com/entireio/cli/cmd/entire/cli/logging"
12		"github.com/spf13/cobra"
13		flag "github.com/spf13/pflag"
14	)
15	
16	// agentHelpAnnotation marks an otherwise-hidden command as worth advertising to
17	// coding agents through `entire agent-help`. Hidden commands (e.g. trail) opt in
18	// by setting Annotations[agentHelpAnnotation] = "true".
19	const agentHelpAnnotation = "entire_agent_help"
20	
21	// agentHelpRequiresTrailsAnnotation marks a command whose surface should only be
22	// advertised to agents when trails are enabled for the repo. While the trails
23	// product may not be available to a user yet, agent-help must not point agents at
24	// commands they can't use — so trail-gated commands are hidden until the same
25	// "is trails enabled" signal the first-turn injection already gates on says yes.
26	const agentHelpRequiresTrailsAnnotation = "entire_agent_help_requires_trails"
27	
28	// agentHelpAnnotationEnabled is the truthy value for the agent-help annotations.
29	const agentHelpAnnotationEnabled = "true"
30	
31	// agentHelpOverview is the only hand-maintained prose in agent-help: a terse,
32	// high-level "what entire is for" plus the standing repo-inference rule. It names
33	// no flags or subcommands — those are rendered live from the installed command
34	// tree — so it changes only when a whole capability area lands, not when a flag
35	// is added.
36	const agentHelpOverview = `Entire's CLI is the source of truth for its own usage. Do not guess flags or
37	subcommands — read them from this command. You are already inside the repo:
38	entire auto-detects it from the git origin remote, so never ask the user for the
39	repo name. Pass --repo only to target a DIFFERENT repo.`
40	
41	// newAgentHelpCmd builds the `entire agent-help` command. It is visible in
42	// `entire help` (so agents on transports without context injection can still
43	// find it) and renders agent-facing usage live from rootCmd's command tree.
44	func newAgentHelpCmd(rootCmd *cobra.Command) *cobra.Command {
45		var asJSON bool
46		cmd := &cobra.Command{
47			Use:   "agent-help [command...]",
48			Short: "Machine-readable usage for coding agents (always matches the installed CLI)",
49			Long: `Prints agent-facing usage for the Entire CLI, generated live from the installed
50	command tree so it always matches this binary. With no arguments it prints a
51	high-level map of when to use entire and which subcommand; pass a command path
52	(e.g. "agent-help checkpoint") to see that command's exact, current flags.`,
53			RunE: func(c *cobra.Command, args []string) error {
54				// Resolve the origin remote once and derive both the repo line and the
55				// trails-enablement check from it (avoids two git subprocesses per run).
56				repoLine, trailsEnabled := agentHelpRepoContext(c.Context())
57				out, err := runAgentHelp(rootCmd, args, repoLine, asJSON, trailsEnabled)
58				if err != nil {
59					return err
60				}
61				fmt.Fprint(c.OutOrStdout(), out)
62				return nil
63			},
64		}
65		cmd.Flags().BoolVar(&asJSON, "json", false, "Emit structured JSON instead of text")
66		return cmd
67	}
68	
69	// agentHelpRepoContext resolves the origin remote ONCE and derives both the repo
70	// line (forge/owner/repo, or "" when it can't be determined — no origin /
71	// detached HEAD — so the renderer degrades gracefully) and whether trails are
72	// enabled for that scope. Unlike the prompt-path gate, agent-help is an explicit
73	// command and can afford to refresh an absent or stale enablement decision rather
74	// than incorrectly treating an unknown cache entry as "trails unavailable".
75	func agentHelpRepoContext(ctx context.Context) (repoLine string, trailsEnabled bool) {
76		return agentHelpRepoContextWithRefresh(ctx, refreshAgentHelpTrailsEnabledCacheIfStaleForScope)
77	}
78	
79	// refreshAgentHelpTrailsEnabledCacheIfStaleForScope refreshes synchronously
80	// because agent-help is an explicit command whose output must reflect the
81	// current availability decision. SessionStart uses the detached
82	// refreshTrailsEnabledCacheIfStaleForScope path instead to avoid hook latency.
83	func refreshAgentHelpTrailsEnabledCacheIfStaleForScope(ctx context.Context, scope trailEnablementScope) error {
84		if cachedTrailsEnablementForScope(ctx, scope, time.Now()) != trailEnablementCacheUnknown {
85			return nil
86		}
87		if !scope.Supported {
88			return saveTrailsEnabledForScope(ctx, scope, false, time.Now())
89		}
90		client, err := NewAuthenticatedAPIClient(ctx, false)
91		if err != nil {
92			return err
93		}
94		_, err = refreshTrailsEnabledCacheForScope(ctx, client, scope)
95		return err
96	}
97	
98	// agentHelpRepoContextWithRefresh keeps the refresh dependency explicit so the
99	// cache-miss behavior can be tested without authenticating against a real API.
100	func agentHelpRepoContextWithRefresh(
101		ctx context.Context,
102		refresh func(context.Context, trailEnablementScope) error,
103	) (repoLine string, trailsEnabled bool) {
104		scope, err := currentTrailEnablementScope(ctx)
105		if err != nil {
106			return "", false
107		}
108		if scope.Forge != "" && scope.Owner != "" && scope.Repo != "" {
109			repoLine = scope.RepoKey
110		}
111	
112		now := time.Now()
113		if decision := cachedTrailsEnablementForScope(ctx, scope, now); decision != trailEnablementCacheUnknown {
114			return repoLine, decision == trailEnablementCacheEnabled
115		}
116	
117		// ResolveDataAPIToken performs data-host discovery before it can reject a
118		// missing login. The scope already carries the locally resolved auth identity,
119		// so avoid making an unauthenticated first run wait on a network request that
120		// cannot produce an enabled decision.
121		if scope.AuthKey == "" {
122			return repoLine, false
123		}
124		if recentAgentHelpTrailsRefreshFailure(ctx, scope, now) {
125			return repoLine, false
126		}
127	
128		refreshCtx, cancel := context.WithTimeout(ctx, trailEnablementRefreshTimeout)
129		defer cancel()
130		if err := refresh(refreshCtx, scope); err != nil {
131			// A separate short backoff keeps an offline authenticated user from paying
132			// this timeout on every agent-help invocation. It must not alter the shared
133			// enablement decision, which SessionStart uses for context injection.
134			if cacheErr := saveAgentHelpTrailsRefreshFailure(ctx, scope, time.Now()); cacheErr != nil {
135				logging.Debug(ctx, "failed to save agent-help trails refresh backoff", "error", cacheErr)
136			}
137			return repoLine, false
138		}
139		return repoLine, cachedTrailsEnablementForScope(ctx, scope, time.Now()) == trailEnablementCacheEnabled
140	}
141	
142	// runAgentHelp resolves args to a command node and renders it. It is pure (no
143	// git / IO): the caller passes the already-resolved repoLine and trailsEnabled.
144	func runAgentHelp(rootCmd *cobra.Command, args []string, repoLine string, asJSON, trailsEnabled bool) (string, error) {
145		target := rootCmd
146		for _, name := range args {
147			child := agentHelpFindChild(target, name)
148			if child == nil {
149				return "", fmt.Errorf("unknown command %q; run `entire agent-help` for the list of commands", name)
150			}
151			// Keep the specific, actionable message for the trail-gated case.
152			if !trailsEnabled && child.Annotations[agentHelpRequiresTrailsAnnotation] == agentHelpAnnotationEnabled {
153				return "", fmt.Errorf("`%s` is unavailable: trails are not enabled for this repo", child.Name())
154			}
155			// The drillable surface must match the advertised surface: a name an agent
156			// guesses for a command the listing intentionally hides (help, deprecated,
157			// or plain-hidden infra like `hooks`) reads as nonexistent here too.
158			if !isAgentHelpAdvertised(child, trailsEnabled) {
159				return "", fmt.Errorf("unknown command %q; run `entire agent-help` for the list of commands", name)
160			}
161			target = child
162		}
163		if asJSON {
164			return renderAgentHelpJSON(rootCmd, target, repoLine, trailsEnabled)
165		}
166		if target == rootCmd {
167			return renderAgentHelpTop(rootCmd, repoLine, trailsEnabled), nil
168		}
169		return renderAgentHelpCommand(target, repoLine, trailsEnabled), nil
170	}
171	
172	// agentHelpFindChild finds a direct child of parent by name or alias. It
173	// includes hidden commands so an annotated one like trail resolves; the caller
174	// (runAgentHelp) then enforces isAgentHelpAdvertised, so the drillable surface
175	// matches the advertised one.
176	func agentHelpFindChild(parent *cobra.Command, name string) *cobra.Command {
177		for _, sub := range parent.Commands() {
178			if sub.Name() == name {
179				return sub
180			}
181			for _, alias := range sub.Aliases {
182				if alias == name {
183					return sub
184				}
185			}
186		}
187		return nil
188	}
189	
190	type agentHelpFlagJSON struct {
191		Name      string `json:"name"`
192		Shorthand string `json:"shorthand,omitempty"`
193		Type      string `json:"type"`
194		Default   string `json:"default,omitempty"`
195		Usage     string `json:"usage"`
196	}
197	
198	type agentHelpSubcommandJSON struct {
199		Name  string `json:"name"`
200		Short string `json:"short"`
201	}
202	
203	type agentHelpJSON struct {
204		Command     string                    `json:"command"`
205		Short       string                    `json:"short,omitempty"`
206		Long        string                    `json:"long,omitempty"`
207		Repo        string                    `json:"repo,omitempty"`
208		Flags       []agentHelpFlagJSON       `json:"flags,omitempty"`
209		Subcommands []agentHelpSubcommandJSON `json:"subcommands,omitempty"`
210	}
211	
212	// renderAgentHelpJSON renders the structured form of a command node.
213	func renderAgentHelpJSON(rootCmd, target *cobra.Command, repoLine string, trailsEnabled bool) (string, error) {
214		doc := agentHelpJSON{
215			Command: target.CommandPath(),
216			Short:   target.Short,
217			Long:    strings.TrimSpace(target.Long),
218			Repo:    repoLine,
219		}
220		if target != rootCmd {
221			collect := func(fs *flag.FlagSet) {
222				fs.VisitAll(func(f *flag.Flag) {
223					if f.Hidden {
224						return
225					}
226					doc.Flags = append(doc.Flags, agentHelpFlagJSON{
227						Name:      f.Name,
228						Shorthand: f.Shorthand,
229						Type:      f.Value.Type(),
230						Default:   f.DefValue,
231						Usage:     f.Usage,
232					})
233				})
234			}
235			collect(target.LocalFlags())
236			collect(target.InheritedFlags())
237		}
238		for _, sub := range agentHelpCommands(target, trailsEnabled) {
239			doc.Subcommands = append(doc.Subcommands, agentHelpSubcommandJSON{Name: sub.Name(), Short: sub.Short})
240		}
241		b, err := json.MarshalIndent(doc, "", "  ")
242		if err != nil {
243			return "", fmt.Errorf("marshal agent-help json: %w", err)
244		}
245		return string(b) + "\n", nil
246	}
247	
248	// isAgentHelpAdvertised reports whether sub should be exposed to agents through
249	// agent-help. The listing AND the drill-down resolver share this predicate so
250	// the drillable surface always matches the advertised surface: visible commands
251	// plus hidden commands that opt in via agentHelpAnnotation, minus the help
252	// command, deprecated commands, and (when trails are disabled) trail-gated ones.
253	func isAgentHelpAdvertised(sub *cobra.Command, trailsEnabled bool) bool {
254		if sub.Name() == "help" || sub.Name() == "agent-help" || sub.Deprecated != "" {
255			return false
256		}
257		if sub.Hidden && sub.Annotations[agentHelpAnnotation] != agentHelpAnnotationEnabled {
258			return false
259		}
260		if !trailsEnabled && sub.Annotations[agentHelpRequiresTrailsAnnotation] == agentHelpAnnotationEnabled {
261			return false
262		}
263		return true
264	}
265	
266	// agentHelpCommands returns the child commands to advertise to agents.
267	func agentHelpCommands(parent *cobra.Command, trailsEnabled bool) []*cobra.Command {
268		var out []*cobra.Command
269		for _, sub := range parent.Commands() {
270			if isAgentHelpAdvertised(sub, trailsEnabled) {
271				out = append(out, sub)
272			}
273		}
274		return out
275	}
276	
277	// agentHelpRepoBlock formats the auto-detected repo line, degrading gracefully
278	// when the repo can't be resolved (no origin / detached HEAD) rather than
279	// implying a repo that isn't there.
280	func agentHelpRepoBlock(repoLine string) string {
281		// Defense-in-depth: this line is emitted as plain text into agent context and
282		// the user's terminal. A crafted origin URL's control characters (newline,
283		// ANSI escapes) are rejected upstream in gitremote, but never let one reach
284		// this plain-text sink — degrade to the not-detectable message instead.
285		if strings.TrimSpace(repoLine) == "" || strings.IndexFunc(repoLine, unicode.IsControl) >= 0 {
286			return "Current repo: not auto-detectable here (no origin remote / detached HEAD); pass --repo explicitly.\n"
287		}
288		return "Current repo: " + repoLine + "  (auto-detected from origin; pass --repo only for a DIFFERENT repo)\n"
289	}
290	
291	// renderAgentHelpCommand renders one resolved command node for an agent: its
292	// path + Short, its Long description, the auto-detected repo line, its live flag
293	// usages (hidden flags are skipped by cobra), and its advertised subcommands.
294	func renderAgentHelpCommand(cmd *cobra.Command, repoLine string, trailsEnabled bool) string {
295		var b strings.Builder
296		fmt.Fprintf(&b, "%s — %s\n", cmd.CommandPath(), cmd.Short)
297		if long := strings.TrimSpace(cmd.Long); long != "" && long != strings.TrimSpace(cmd.Short) {
298			b.WriteString(long)
299			b.WriteString("\n")
300		}
301		b.WriteString("\n")
302		b.WriteString(agentHelpRepoBlock(repoLine))
303	
304		// LocalFlags()/InheritedFlags() trigger cobra's persistent-flag merge (plain
305		// Flags() does not without Execute) and skip hidden flags in FlagUsages.
306		if usages := strings.TrimRight(cmd.LocalFlags().FlagUsages(), "\n"); usages != "" {
307			b.WriteString("\nFlags:\n")
308			b.WriteString(usages)
309			b.WriteString("\n")
310		}
311		if usages := strings.TrimRight(cmd.InheritedFlags().FlagUsages(), "\n"); usages != "" {
312			b.WriteString("\nInherited flags:\n")
313			b.WriteString(usages)
314			b.WriteString("\n")
315		}
316	
317		if subs := agentHelpCommands(cmd, trailsEnabled); len(subs) > 0 {
318			names := make([]string, 0, len(subs))
319			for _, sub := range subs {
320				names = append(names, sub.Name())
321			}
322			fmt.Fprintf(&b, "\nSubcommands: %s\n", strings.Join(names, " · "))
323			fmt.Fprintf(&b, "Next:  entire agent-help %s <subcommand>\n", strings.TrimPrefix(cmd.CommandPath(), cmd.Root().Name()+" "))
324		}
325		return b.String()
326	}
327	
328	// renderAgentHelpTop renders the top-level agent-facing overview: the curated
329	// intro + rule, the auto-detected repo line, and a live map of the advertised
330	// commands (their Short help), ending with the drill-down pointer.
331	func renderAgentHelpTop(rootCmd *cobra.Command, repoLine string, trailsEnabled bool) string {
332		var b strings.Builder
333		b.WriteString(agentHelpOverview)
334		b.WriteString("\n\n")
335		b.WriteString(agentHelpRepoBlock(repoLine))
336		b.WriteString("\nWhen to use entire:\n")
337		for _, sub := range agentHelpCommands(rootCmd, trailsEnabled) {
338			fmt.Fprintf(&b, "  %-12s %s\n", sub.Name(), sub.Short)
339		}
340		// Use an example command that is actually advertised here (trail is gated on
341		// trails being enabled), so we never point at a command the agent can't use.
342		example := "checkpoint"
343		if trailsEnabled {
344			example = "trail"
345		}
346		fmt.Fprintf(&b, "\nDrill in for exact, currently-installed flags:  entire agent-help <command>  (e.g. entire agent-help %s)\n", example)
347		b.WriteString("Add --json for structured output.\n")
348		return b.String()
349	}
