func TestRenderAgentHelpCommand_RendersExample(t *testing.T) {
	t.Parallel()

	cmd := &cobra.Command{
		Use:     "why <file>[:line]",
		Short:   "Show why a line exists",
		Example: "  entire why src/auth.go:42 --json",
	}

